// Navbar: sits transparent over the hero, turns solid once you scroll past it.
(function () {
  var nav = document.querySelector(".nav_component");
  if (!nav) return;
  var hero = document.querySelector(".hero_component");
  if (!hero) { nav.classList.add("is-solid", "is-static"); return; } // pages without a hero: the nav sits in flow under the ticker and sticks below it
  nav.classList.add("is-over-hero");
  function onScroll() {
    nav.classList.toggle("is-solid", window.scrollY > 40);
  }
  window.addEventListener("scroll", onScroll, { passive: true }); onScroll();
})();

// Phone tabs: mark the page you're on (blog posts count as Updates, Collectives as Sponsor). Webflow adds w--current itself on exact matches.
(function () {
  function norm(p) { return p.replace(/(index)?(\.html)?$/, "").replace(/\/$/, ""); }
  var here = norm(location.pathname);
  document.querySelectorAll(".appbar_tab").forEach(function (a) {
    var t = norm(a.pathname);
    var on = t === here || (/(updates|blog-post)$/.test(t) && /\/blog\//.test(here)) || (/sponsorship$/.test(t) && /collectives$/.test(here));
    a.classList.toggle("is-current", on);
    if (on) a.setAttribute("aria-current", "page");
  });
})();

// Reveal on scroll.
(function () {
  var els = document.querySelectorAll(".reveal");
  if (/static/.test(location.search)) { els.forEach(function (e) { e.classList.add("is-in"); }); return; }
  if (!("IntersectionObserver" in window)) { els.forEach(function (e) { e.classList.add("is-in"); }); return; }
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add("is-in"); io.unobserve(en.target); } });
  }, { rootMargin: "0px 0px -8% 0px" });
  els.forEach(function (e) { io.observe(e); });
})();

// Bike hotspots: hover or tap a number to swap the detail card. Part 5 shows the fit graphic instead of a photo.
(function () {
  var spots = document.querySelectorAll(".hotspot");
  if (!spots.length) return;
  var panel = document.querySelector(".bike_panel"), img = panel.querySelector(".bike_panel-media img"),
      no = panel.querySelector("[data-part-no]"), title = panel.querySelector("[data-part-title]"), text = panel.querySelector("[data-part-text]");
  function show(s) {
    if (s.classList.contains("is-active") && panel.dataset.ready) return;
    panel.dataset.ready = 1;
    spots.forEach(function (x) { x.classList.toggle("is-active", x === s); });
    var fit = s.hasAttribute("data-fit");
    panel.classList.toggle("is-fit", fit);
    if (window.dcbFit) window.dcbFit(fit);
    if (!fit) {
      img.style.opacity = 0;
      setTimeout(function () { img.src = s.dataset.img; img.alt = s.dataset.title; img.style.objectPosition = s.dataset.pos || "50% 50%"; img.style.opacity = 1; }, 150);
    }
    no.textContent = s.textContent.trim(); title.textContent = s.dataset.title; text.textContent = s.dataset.text;
  }
  spots.forEach(function (s) { s.addEventListener("click", function () { show(s); }); s.addEventListener("mouseenter", function () { show(s); }); });
  var part = location.search.match(/part=(\d)/);
  if (part) addEventListener("load", function () { show(spots[+part[1] - 1]); });
})();

