// FAQ search + topic chips.
(function () {
  var input = document.querySelector("[data-faq-search]");
  if (!input) return;
  var items = document.querySelectorAll(".qa_item"), chips = document.querySelectorAll(".chip"), groups = document.querySelectorAll("[data-faq-group]");
  var empty = document.querySelector(".faq-empty"), topic = "all";
  function apply() {
    var q = input.value.trim().toLowerCase(), shown = 0;
    items.forEach(function (it) {
      var ok = (topic === "all" || it.dataset.topic === topic) && (!q || it.textContent.toLowerCase().indexOf(q) > -1);
      it.style.display = ok ? "" : "none"; if (ok) shown++;
      if (q && ok) it.open = true;
    });
    groups.forEach(function (g) { g.style.display = g.querySelectorAll('.qa_item:not([style*="none"])').length ? "" : "none"; });
    empty.style.display = shown ? "none" : "block";
  }
  input.addEventListener("input", apply);
  chips.forEach(function (c) { c.addEventListener("click", function () {
    topic = c.dataset.topic; chips.forEach(function (x) { x.classList.toggle("is-active", x === c); }); apply();
  }); });
})();



// Image takeover: --t goes 0 -> 1 across the section.
(function () {
  var el = document.querySelector("[data-takeover]");
  if (!el) return;
  function upd() { var r = el.getBoundingClientRect(), max = el.offsetHeight - innerHeight;
    var t = Math.min(Math.max(-r.top / (max * 0.8), 0), 1); el.style.setProperty("--t", t.toFixed(3)); }
  addEventListener("scroll", upd, { passive: true }); upd();
})();

// Slot reels: digits tick through random numbers fast, then slow, then land (once, on first view).
(function () {
  var els = document.querySelectorAll("[data-reel]");
  if (!els.length) return;
  var still = window.matchMedia("(prefers-reduced-motion: reduce)").matches || /static/.test(location.search);
  function run(el) {
    var final = el.textContent.trim(); if (still) return;
    el.textContent = "";
    final.split("").forEach(function (ch, i) {
      var s = document.createElement("span"); s.className = "reel_slot"; s.textContent = /\d/.test(ch) ? "0" : ch; el.appendChild(s);
      if (!/\d/.test(ch)) return;
      var start = performance.now() + i * 60, dur = 1000;
      (function tick() {
        var now = performance.now(), k = (now - start) / dur;
        if (k >= 1) { s.textContent = ch; return; }
        if (k > 0) s.textContent = String(Math.floor(Math.random() * 10));
        setTimeout(tick, k < 0.6 ? 40 : 40 + (k - 0.6) * 700);
      })();
    });
  }
  var io = new IntersectionObserver(function (es) { es.forEach(function (e) { if (e.isIntersecting) { run(e.target); io.unobserve(e.target); } }); }, { threshold: 0.6 });
  els.forEach(function (e) { io.observe(e); });
})();


// Fare card: tabs, ride-length slider, member plans. Numbers count to their new value.
(function () {
  var card = document.querySelector("[data-fare]");
  if (!card) return;
  function money(v) { return "$" + (Math.round(v * 100) % 100 ? v.toFixed(2) : String(Math.round(v))); }
  function tweenTo(el, to) {
    var from = parseFloat(el.textContent.replace(/[^0-9.]/g, "")) || 0, o = { v: from };
    if (!window.gsap) { el.textContent = money(to); return; }
    gsap.to(o, { v: to, duration: .55, ease: "power2.out", onUpdate: function () { el.textContent = money(o.v); }, onComplete: function () { el.textContent = money(to); } });
  }
  card.querySelectorAll("[data-fare-tab]").forEach(function (b) {
    b.addEventListener("click", function () {
      var mode = b.dataset.fareTab; card.dataset.mode = mode;
      card.querySelectorAll("[data-fare-tab]").forEach(function (x) { var on = x === b; x.classList.toggle("is-active", on); x.setAttribute("aria-selected", on); });
      card.querySelectorAll("[data-fare-pane]").forEach(function (p) { p.classList.toggle("is-active", p.dataset.farePane === mode); });
    });
  });
  var hours = card.querySelector("[data-fare-hours]"), range = card.querySelector("[data-fare-range]"), out = card.querySelector("[data-fare-out]"),
      total = card.querySelector("[data-fare-total]"), cap = card.querySelector("[data-fare-caption]");
  for (var i = 0; i < 6; i++) { var h = document.createElement("span"); h.className = "fare_hour"; h.textContent = i ? "+$4.50" : "$5.50"; hours.appendChild(h); }
  function setHours() {
    var n = +range.value;
    hours.querySelectorAll(".fare_hour").forEach(function (h, i) { h.classList.toggle("is-on", i < n); });
    out.textContent = n + (n === 1 ? " hour" : " hours");
    cap.textContent = n === 1 ? "for a one-hour ride" : "for a " + n + "-hour ride";
    tweenTo(total, 5.5 + 4.5 * (n - 1));
  }
  range.addEventListener("input", setHours); setHours();
  var mprice = card.querySelector("[data-fare-mprice]"), mcap = card.querySelector("[data-fare-mcaption]");
  card.querySelectorAll("[data-plan]").forEach(function (b) {
    b.addEventListener("click", function () {
      card.querySelectorAll("[data-plan]").forEach(function (x) { x.classList.toggle("is-active", x === b); });
      tweenTo(mprice, +b.dataset.price); mcap.textContent = b.dataset.cap;
    });
  });
  if (/fare=member/.test(location.search)) card.querySelector('[data-fare-tab="member"]').click();
  var hrs = location.search.match(/hours=(\d)/);
  if (hrs) { range.value = hrs[1]; setHours(); }
})();

// Fleet tiles: 90 dots (10 gold = pedal-assist), a 15 mph gauge, three struck-out words. Plays once on first view.
(function () {
  var fleet = document.querySelector("[data-fleet]");
  if (!fleet) return;
  var dots = fleet.querySelector(".fleet_dots");
  for (var i = 0; i < 90; i++) { var d = document.createElement("i"); if (i >= 80) d.className = "is-assist"; dots.appendChild(d); }
  var gauge = fleet.querySelector("[data-gauge]"), len = gauge.getTotalLength();
  gauge.style.strokeDasharray = len; gauge.style.strokeDashoffset = len * (1 - 15 / 20);
  if (!window.gsap || /static/.test(location.search)) return;
  gauge.style.strokeDashoffset = len;
  var strikes = fleet.querySelectorAll(".fleet_swap s");
  strikes.forEach(function (li) { li.style.setProperty("--s", 0); });
  ScrollTrigger.create({ trigger: fleet, start: "top 80%", once: true, onEnter: function () {
    gsap.from(dots.children, { scale: 0, opacity: 0, duration: .35, stagger: .008, ease: "back.out(2)" });
    gsap.to(gauge, { strokeDashoffset: len * (1 - 15 / 20), duration: 1.4, ease: "power3.out", delay: .2 });
    gsap.to(strikes, { "--s": 1, duration: .45, stagger: .3, delay: .5, ease: "power2.inOut" });
  } });
})();

// How to ride: pin the section; scrolling moves the bike from stop to stop. At the last stop it docks and the rider walks off.
(function () {
  var sec = document.querySelector("[data-route]");
  if (!sec || !window.gsap || !window.ScrollTrigger || matchMedia("(max-width: 767px)").matches) return;
  gsap.registerPlugin(ScrollTrigger);
  var track = sec.querySelector("[data-route-track]"), puck = sec.querySelector("[data-route-puck]"), walker = sec.querySelector("[data-route-walker]"),
      fill = sec.querySelector("[data-route-fill]"), stops = sec.querySelectorAll(".route_stop"), ol = sec.querySelector(".route_line");
  function x(i) { return function () { return ol.offsetLeft + stops[i].offsetLeft; }; }
  function rail() { return track.clientWidth - puck.offsetWidth / 2; }
  function fx(i) { return function () { return x(i)() / rail(); }; }
  var tl = gsap.timeline({ defaults: { ease: "power2.inOut", duration: 1 } });
  tl.set(puck, { x: x(0) }).set(fill, { scaleX: 0 }).to({}, { duration: .4 });
  for (var i = 1; i < 4; i++) tl.to(puck, { x: x(i) }, "s" + i).to(fill, { scaleX: fx(i) }, "s" + i).to({}, { duration: .5 });
  tl.addLabel("dock").to(puck, { autoAlpha: 0, scale: .6, duration: .3 }, "dock")
    .fromTo(walker, { x: x(3), autoAlpha: 0 }, { autoAlpha: 1, duration: .3 }, "dock+=.15")
    .to(walker, { x: function () { return track.clientWidth - walker.offsetWidth; }, duration: 1.3, ease: "none" }, "dock+=.45")
    .to(fill, { scaleX: 1, duration: 1.3, ease: "none" }, "dock+=.45");
  var dockAt = tl.labels.dock;
  ScrollTrigger.create({
    trigger: sec, pin: sec.querySelector(".route_pin"), start: "top top", end: "+=230%", scrub: .5, animation: tl, invalidateOnRefresh: true,
    onUpdate: function () {
      var px = gsap.getProperty(puck, "x"), t = tl.time();
      stops.forEach(function (s, i) { s.classList.toggle("is-active", px >= x(i)() - 4 || t >= dockAt); });
      sec.classList.toggle("is-docked", t >= dockAt + .1);
    }
  });
})();

// Timeline rider, drawn in the bike's 72-unit space (ground at y 42.8): one bike and a pedalling rider. host sets the width
// the ride covers. Returns render(progress): 0 at 2017 on the left, 1 at 2026 on the right.
window.dcbActors = function (svg, host) {
  if (!svg) return null;
  var INK = "#0d0d0c", H = 150;
  var BIKE = '<circle cx="14" cy="30" r="12"/><circle cx="58" cy="30" r="12"/>' +
    '<g class="spokes" stroke-width=".55"><path d="M14 18V42M2 30H26M5.5 21.5l17 17M22.5 21.5l-17 17"/></g><g class="spokes" stroke-width=".55"><path d="M58 18V42M46 30H70M49.5 21.5l17 17M66.5 21.5l-17 17"/></g>' +
    '<path d="M1.5 25.5A12.6 12.6 0 0 1 21 19.5M50 21A12.6 12.6 0 0 1 68 23M14 30L33 31L28.5 13M14 30L28.5 15M33 31C40 30 46 24 50 15.5L51 11.5M50 15.5L58 30M51 11.5L49 7L43.5 8"/>' +
    '<path d="M24.5 12.2H32.5" stroke-width="2.2"/><path d="M47 8.5h9l-1 6h-7z"/><circle cx="33" cy="31" r="3"/><path class="crank"/>';
  var LIMB = 'fill="none" stroke="' + INK + '" stroke-linecap="round" stroke-linejoin="round"';
  svg.setAttribute("height", H);
  svg.innerHTML = '<g class="root" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" stroke="' + INK + '">' +
    '<g class="ride"><g class="bike">' + BIKE + '</g><g class="rider"><path class="far" ' + LIMB + ' stroke-width="2.4" opacity=".45"/><path class="body" ' + LIMB + ' stroke-width="2.8"/><path class="near" ' + LIMB + ' stroke-width="2.6"/><circle cx="35.2" cy="-16.2" r="4.2" fill="' + INK + '" stroke="none"/></g></g></g>';
  var root = svg.querySelector(".root"), ride = svg.querySelector(".ride"), rider = svg.querySelector(".rider"),
      crank = svg.querySelector(".crank"), spokes = svg.querySelectorAll(".spokes"), k, W;
  function layout() {
    W = host.clientWidth; k = Math.max(.75, Math.min(1.35, W / 900)); svg.setAttribute("width", W);
    root.setAttribute("transform", "translate(0 " + H + ") scale(" + k + ") translate(0 -42.8)");
  }
  layout(); addEventListener("resize", layout);
  function pt(p) { return p[0].toFixed(2) + " " + p[1].toFixed(2); }
  function leg(hip, foot, a, b) { // two-bone reach, knee bends forward
    var dx = foot[0] - hip[0], dy = foot[1] - hip[1], d = Math.min(Math.hypot(dx, dy), a + b - .01), t = Math.atan2(dy, dx),
        al = Math.acos((a * a + d * d - b * b) / (2 * a * d)), kn = [hip[0] + a * Math.cos(t - al), hip[1] + a * Math.sin(t - al)];
    return "M" + pt(hip) + "L" + pt(kn) + "L" + pt(foot);
  }
  function pedal(th) {
    var bb = [33, 31], r = 5.5, hip = [27.5, 10], f1 = [bb[0] + r * Math.cos(th), bb[1] + r * Math.sin(th)], f2 = [bb[0] - r * Math.cos(th), bb[1] - r * Math.sin(th)];
    crank.setAttribute("d", "M" + pt(f2) + "L" + pt(f1));
    rider.querySelector(".far").setAttribute("d", leg(hip, f2, 14.5, 15.5));
    rider.querySelector(".near").setAttribute("d", leg(hip, f1, 14.5, 15.5) + "M33 -10L39.5 -1.5L44 8");
    rider.querySelector(".body").setAttribute("d", "M27.5 10L33 -10");
  }
  return function (p) {
    var x = Math.max(0, Math.min(1, p)) * (W / k - 72);
    ride.setAttribute("transform", "translate(" + x.toFixed(2) + " 0)");
    var rot = x / 12 * 57.3;
    spokes[0].setAttribute("transform", "rotate(" + rot + " 14 30)"); spokes[1].setAttribute("transform", "rotate(" + rot + " 58 30)");
    pedal(x / 12 * .55 + 1.2);
  };
};

// Story timeline: a rider pedals the ruler from 2017 to 2026 as you scroll past it.
(function () {
  var ruler = document.querySelector(".ruler");
  if (!ruler || !window.gsap || !window.ScrollTrigger) return;
  var render = window.dcbActors(ruler.querySelector("[data-ruler-actors]"), ruler);
  if (!render) return;
  render(0);
  ScrollTrigger.create({ trigger: ruler, start: "top 92%", end: "top 22%", scrub: .6, onUpdate: function (self) { render(self.progress); } });
})();

// Station tower sequence: pin the section, move the camera over Ian's sign art, swap the copy, then show a one-way trip.
(function () {
  var sec = document.querySelector("[data-docks]");
  if (!sec || !window.gsap || !window.ScrollTrigger) return;
  gsap.registerPlugin(ScrollTrigger);
  var tower = sec.querySelector("[data-docks-tower]"), sign = sec.querySelector("[data-docks-sign]"), stage = sec.querySelector(".docks_stage"),
      trip = sec.querySelector("[data-docks-trip]"), beats = sec.querySelectorAll("[data-beat]"), line = sec.querySelector("[data-docks-line]");
  // Panels as fractions of the sign's height (vector sign, 1000 x 4000): START 0.175-0.475, LOCK & END 0.505-0.71.
  var START = { top: .175, h: .3 }, END = { top: .505, h: .205 };
  // Zoom as far as the whole panel (and the tower's width) still fits inside the stage.
  function fit(p) { return Math.min(stage.clientHeight * .94 / (p.h * sign.offsetHeight), stage.clientWidth * .97 / tower.offsetWidth, 3.6); }
  function sc(p) { return function () { return fit(p); }; }
  function yp(p) { return function () { var f = (sign.offsetTop + (p.top + p.h / 2) * sign.offsetHeight) / tower.offsetHeight; return -(f - .5) * fit(p) * 100; }; }
  var tl = gsap.timeline({ defaults: { ease: "power2.inOut", duration: 1 } });
  tl.to({}, { duration: 1.9 })
    .to(tower, { scale: sc(START), yPercent: yp(START) }, "b1")
    .to(beats[0], { autoAlpha: 0, y: -20, duration: .5 }, "b1")
    .fromTo(beats[1], { autoAlpha: 0, y: 20 }, { autoAlpha: 1, y: 0, duration: .5 }, "b1+=.5")
    .to({}, { duration: .7 })
    .to(tower, { scale: sc(END), yPercent: yp(END) }, "b2")
    .to(beats[1], { autoAlpha: 0, y: -20, duration: .5 }, "b2")
    .fromTo(beats[2], { autoAlpha: 0, y: 20 }, { autoAlpha: 1, y: 0, duration: .5 }, "b2+=.5")
    .to({}, { duration: .7 })
    .to(tower, { scale: 1, yPercent: 0, xPercent: function () { return innerWidth < 768 ? -150 : -55; } }, "b3") // phones: the tower steps aside so the trip card sits beside it
    .to(trip, { autoAlpha: 1, y: 0, duration: .6 }, "b3+=.5")
    .fromTo(line, { strokeDashoffset: 64 }, { strokeDashoffset: 0, duration: .6, ease: "none" }, "b3+=.8")
    .to(beats[2], { autoAlpha: 0, y: -20, duration: .5 }, "b3")
    .fromTo(beats[3], { autoAlpha: 0, y: 20 }, { autoAlpha: 1, y: 0, duration: .5 }, "b3+=.5")
    .to({}, { duration: .5 });
  if (/scene=pier/.test(location.search)) sec.classList.add("is-pier");
  ScrollTrigger.create({
    trigger: sec, pin: sec.querySelector(".docks_pin"), start: "top top", end: "+=" + (beats.length * 95 + 80) + "%", scrub: .6, animation: tl, invalidateOnRefresh: true,
    onToggle: function (self) { document.body.classList.toggle("is-docking", self.isActive); } // phones hide the app bar while pinned
  });
})();

// Station map: hovering (or, on phones, scrolling past) a station flies the map to its pin and spotlights it.
(function () {
  var fig = document.querySelector("[data-smap]");
  if (!fig) return;
  var box = fig.querySelector(".smap_box"), cam = fig.querySelector(".smap_cam"), veil = fig.querySelector(".smap_veil"),
      ring = fig.querySelector(".smap_ring"), tag = fig.querySelector(".smap_tag"), rows = [].slice.call(document.querySelectorAll(".board_row[data-x]")),
      board = document.querySelector(".board"), phone = matchMedia("(max-width: 991px)"), on = null;
  function view(x, y, k) {
    var cw = box.clientWidth, ch = box.clientHeight, S = cw;
    var tx = Math.min(0, Math.max(cw - S * k, cw / 2 - x * S * k)), ty = Math.min(0, Math.max(ch - S * k, ch / 2 - y * S * k));
    cam.style.transform = "translate(" + tx + "px," + ty + "px) scale(" + k + ")";
    return [tx + x * S * k, ty + y * S * k];
  }
  function rest() {
    on = null; rows.forEach(function (r) { r.classList.remove("is-on"); }); fig.classList.remove("is-on");
    if (phone.matches) view(.36, .38, 1.45); else view(.5, .5, 1);
  }
  function show(row) {
    if (on === row) return; on = row;
    rows.forEach(function (r) { r.classList.toggle("is-on", r === row); });
    var p = view(row.dataset.x / 100, row.dataset.y / 100, phone.matches ? 2 : 1.75);
    box.style.setProperty("--vx", p[0] + "px"); box.style.setProperty("--vy", p[1] + "px");
    ring.style.transform = tag.style.transform = "translate(" + p[0] + "px," + p[1] + "px)";
    var zone = row.querySelector(".board_zone");
    tag.innerHTML = "<i class=\"" + zone.className.replace("board_zone", "smap_dot") + "\"></i>" + row.querySelector(".board_name").textContent;
    var tw = tag.offsetWidth, gap = parseFloat(getComputedStyle(document.documentElement).fontSize) * 2.4;
    var right = p[0] + gap + tw <= box.clientWidth - 8, left = p[0] - gap - tw >= 8;
    tag.classList.toggle("is-left", !right && left); tag.classList.toggle("is-below", !right && !left);
    fig.classList.add("is-on");
  }
  rows.forEach(function (r) {
    r.addEventListener("mouseenter", function () { if (!phone.matches) show(r); });
    r.addEventListener("focus", function () { show(r); });
    r.addEventListener("click", function () { show(r); });
  });
  board.addEventListener("mouseleave", function () { if (!phone.matches) rest(); });
  // Phones: map and list pin together under the nav; scrolling through the section steps through the stations in order,
  // and the list slides so the highlighted station sits just under the map.
  var scroller = document.querySelector("[data-sscroll]"), pin = scroller && scroller.querySelector(".stations_pin"), list = board.parentNode;
  function follow() {
    if (!phone.matches || !scroller) { board.style.transform = ""; return; }
    var r = scroller.getBoundingClientRect(), top = parseFloat(getComputedStyle(pin).top) || 0, max = r.height - pin.offsetHeight;
    var p = (top - r.top) / max;
    if (p < 0) { if (on) rest(); board.style.transform = ""; return; }
    var i = Math.max(0, Math.min(rows.length - 1, Math.floor(p * rows.length)));
    show(rows[i]);
    var y = Math.max(0, Math.min(board.offsetHeight - list.clientHeight + 16, rows[i].offsetTop - list.clientHeight * .3));
    board.style.transform = "translateY(" + (-y) + "px)";
  }
  addEventListener("scroll", follow, { passive: true });
  addEventListener("resize", function () { var r = on; on = null; r ? show(r) : rest(); });
  rest();
  if (/[?&]station=(\d+)/.test(location.search)) show(rows[+location.search.match(/[?&]station=(\d+)/)[1] - 1]);
})();

// Get the app: the phone steps through its four screens on a slow loop while it's on screen.
(function () {
  var box = document.querySelector("[data-appdl]");
  if (!box) return;
  var scr = box.querySelectorAll(".scr"), i = 0, t = null;
  function next() { scr[i].classList.remove("is-on"); i = (i + 1) % scr.length; scr[i].classList.add("is-on"); }
  new IntersectionObserver(function (e) {
    if (e[0].isIntersecting) { if (!t) t = setInterval(next, 2600); } else { clearInterval(t); t = null; }
  }).observe(box);
})();

// Why ride: visitor / local tabs.
(function () {
  var sec = document.querySelector("[data-why]");
  if (!sec) return;
  sec.querySelectorAll("[data-why-tab]").forEach(function (b) {
    b.addEventListener("click", function () {
      var mode = b.dataset.whyTab; sec.dataset.mode = mode;
      sec.querySelectorAll("[data-why-tab]").forEach(function (x) { var on = x === b; x.classList.toggle("is-active", on); x.setAttribute("aria-selected", on); });
      // The panes box follows the open tab (inactive pane is absolute), easing between the two heights.
      var box = sec.querySelector(".why_panes"), from = box.offsetHeight;
      sec.querySelectorAll("[data-why-pane]").forEach(function (p) { p.classList.toggle("is-active", p.dataset.whyPane === mode); });
      var to = sec.querySelector(".why_pane.is-active").offsetHeight;
      box.style.height = from + "px"; void box.offsetHeight; box.style.height = to + "px";
      clearTimeout(box._t);
      box._t = setTimeout(function () { box.style.height = ""; if (window.ScrollTrigger) ScrollTrigger.refresh(); }, 560);
    });
  });
  if (/why=local/.test(location.search)) sec.querySelector('[data-why-tab="local"]').click();
})();

// Footer line: size "Ride the old city." to fill the container exactly.
(function () {
  var el = document.querySelector("[data-fit-text]");
  if (!el) return;
  function fit() { el.style.fontSize = "100px"; var w = el.scrollWidth, room = el.parentElement.clientWidth; el.style.fontSize = (100 * room / w * .995) + "px"; }
  (document.fonts ? document.fonts.ready : Promise.resolve()).then(fit);
  addEventListener("resize", fit); fit();
})();

// ScrollTriggers above are created in script order, not page order; sort so pin spacing stacks correctly.
if (window.ScrollTrigger) { ScrollTrigger.sort(); ScrollTrigger.refresh(); }

// Anchor links and deep links. CSS smooth scrolling is off (ScrollTrigger measures by jumping the scroll, and a smooth jump
// left the station tower pinned thousands of pixels early on any page opened at #anchor), so links glide here instead.
// After fonts settle, re-measure and land a deep link on its section, which the pin spacers have moved since the first jump.
(function () {
  var reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  function go(id, smooth) {
    var el = id && document.getElementById(id);
    if (el) scrollTo({ top: el.getBoundingClientRect().top + scrollY, behavior: smooth && !reduced ? "smooth" : "auto" });
    return !!el;
  }
  document.addEventListener("click", function (e) {
    var a = e.target.closest('a[href^="#"]');
    if (a && a.getAttribute("href").length > 1 && go(a.getAttribute("href").slice(1), true)) { e.preventDefault(); history.pushState(null, "", a.getAttribute("href")); }
  });
  (document.fonts ? document.fonts.ready : Promise.resolve()).then(function () {
    if (window.ScrollTrigger) ScrollTrigger.refresh();
    if (location.hash) go(location.hash.slice(1), false);
  });
})();

/* ---- v3.js ---- */
// Mockup v3 (Showcase) behavior, on top of v2.js. In Webflow: one hosted script keyed off data-tour / data-rail.

// Bike tour: one pinned stage, scroll progress p (0..1) drives a camera over the real bike.
// Each key: focus point on the bike (fx, fy as a fraction of the image), where that point sits on screen (tx, ty as a fraction
// of the stage), zoom s, tilt rx/ry in degrees, focus-marker fade dof, headlamp, and light angle la.
(function () {
  var tour = document.querySelector("[data-tour]");
  if (!tour) return;
  var pin = tour.querySelector(".tour_pin"), cam = tour.querySelector("[data-tour-cam]"), bike = tour.querySelector("[data-tour-bike]"),
      sharp = bike.querySelector(".tour_sharp"), focus = tour.querySelector("[data-tour-focus]"),
      focusNo = tour.querySelector("[data-tour-focus-no]"), spot = tour.querySelector(".tour_spot"),
      steps = [].slice.call(tour.querySelectorAll("[data-tour-steps] li")), fitCard = tour.querySelector("[data-tour-fit]"),
      nav = document.querySelector(".nav_component");
  var reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  var beats = [].slice.call(tour.querySelectorAll("[data-tour-beat]")).map(function (el) {
    var r = el.dataset.tourBeat.split(",").map(parseFloat); return { el: el, a: r[0], b: r[1], v: -1 };
  });
  var cards = beats.filter(function (b) { return b.el.classList.contains("tour_card"); });

  function K(p, fx, fy, s, tx, ty, ry, rx, dof, lamp, la, ring) { return { p: p, v: [fx, fy, s, tx, ty, ry, rx, dof, lamp, la], ring: ring || 0 }; }
  // desktop: copy on the left, so the camera puts the part at 64% across
  var DESK = [
    K(0.000, .50, .52, .96, .66, .55, -6, 2.5, 0, 0, 118),
    K(0.070, .50, .52, 1.02, .65, .54, -3, 1.5, 0, 0, 112),
    K(0.125, .30, .745, 2.25, .64, .52, 4, 1, 1, 0, 96, 1),   // 1 belt
    K(0.195, .30, .745, 2.4, .64, .51, 2, 0, 1, 0, 100, 1),
    K(0.255, .615, .09, 2.25, .63, .44, -4, -2, 1, 0, 132, 2), // 2 twist shifter
    K(0.325, .615, .09, 2.4, .63, .45, -2, -1.5, 1, 0, 128, 2),
    K(0.385, .80, .672, 2.3, .64, .5, 5, 1.5, 1, 0, 84, 3),    // 3 drum brake
    K(0.455, .80, .672, 2.45, .64, .5, 3, 1, 1, 0, 88, 3),
    K(0.515, .742, .378, 2.15, .58, .5, 6, 0, 1, 1, 70, 4),    // 4 headlamp
    K(0.585, .742, .378, 2.3, .58, .5, 4, 0, 1, 1, 74, 4),
    K(0.645, .50, .55, .98, .67, .55, -2, 1.5, 0, .35, 110),   // 5 fit: the whole bike
    K(0.715, .50, .55, 1.02, .67, .55, 1, 1, 0, .35, 106),
    K(0.775, .60, .36, 1.75, .64, .5, -5, 0, .7, 0, 124, 6),   // 6 wordmark, gold marks, basket
    K(0.845, .60, .36, 1.85, .64, .5, -3, 0, .7, 0, 120, 6),
    K(0.905, .50, .55, .8, .69, .56, -5, 2, 0, 1, 112),        // outro: back out, lamp on
    K(1.000, .50, .55, .78, .70, .56, -7, 2.5, 0, 1, 116)
  ];
  // phones: copy is a sheet at the bottom, so the part sits in the upper third
  var PHONE = [
    K(0.000, .50, .52, .98, .5, .7, -5, 2, 0, 0, 118),
    K(0.070, .50, .52, 1.0, .5, .69, -3, 1.5, 0, 0, 112),
    K(0.125, .27, .66, 1.85, .5, .42, 4, 1, 1, 0, 96, 1),
    K(0.195, .27, .66, 1.95, .5, .42, 2, 0, 1, 0, 100, 1),
    K(0.255, .615, .09, 2.1, .5, .42, -4, -2, 1, 0, 132, 2),
    K(0.325, .615, .09, 2.23, .5, .42, -2, -1.5, 1, 0, 128, 2),
    K(0.385, .80, .672, 2.1, .5, .42, 5, 1.5, 1, 0, 84, 3),
    K(0.455, .80, .672, 2.23, .5, .42, 3, 1, 1, 0, 88, 3),
    K(0.515, .742, .378, 2.02, .42, .42, 6, 0, 1, 1, 70, 4),
    K(0.585, .742, .378, 2.14, .42, .42, 4, 0, 1, 1, 74, 4),
    K(0.645, .50, .55, .98, .5, .42, -2, 1.5, 0, .35, 110),
    K(0.715, .50, .55, 1.0, .5, .42, 1, 1, 0, .35, 106),
    K(0.775, .60, .36, 1.68, .5, .42, -5, 0, .7, 0, 124, 6),
    K(0.845, .60, .36, 1.76, .5, .42, -3, 0, .7, 0, 120, 6),
    K(0.905, .50, .55, .92, .5, .75, -5, 2, 0, 1, 112),
    K(1.000, .50, .55, .9, .5, .75, -7, 2.5, 0, 1, 116)
  ];

  // where each part is on the bike image; the marker and the sharp window sit here even when the camera frames wider
  var PHONE_S = [PHONE[0].v[2], PHONE[1].v[2]];

  var PART = { 1: [.30, .745], 2: [.615, .09], 3: [.80, .672], 4: [.742, .378], 6: [.60, .36] };
  var phone = matchMedia("(max-width: 767px)"), KEYS = DESK;
  var SW = 0, SH = 0, BW = 0, BH = 0, RATIO = 1360 / 2048;
  function layout() {
    KEYS = phone.matches ? PHONE : DESK;
    SW = pin.clientWidth; SH = pin.clientHeight;
    BW = phone.matches ? SW * .94 : Math.min(SW * .6, (SH - 150) * .86 / RATIO);
    BH = BW * RATIO;
    cam.style.width = BW + "px"; cam.style.height = BH + "px";
    cam.style.left = (SW - BW) / 2 + "px"; cam.style.top = (SH - BH) / 2 + "px";
    if (phone.matches) {
      // intro frames: the bike sits under the copy (it ran under the lede on short phones), shrinking if the screen runs out
      var intro = tour.querySelector(".tour_intro"), below = intro.offsetTop + intro.offsetHeight + 20;
      [0, 1].forEach(function (i) {
        var k = PHONE[i].v, s = Math.min(PHONE_S[i], (SH - below - 12) / BH);
        k[2] = Math.max(s, .7); k[4] = Math.max(.7, (below + BH * k[2] * k[1]) / SH);
      });
    }
  }

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function ease(t) { return t * t * (3 - 2 * t); }
  function sample(p) {
    var i = 0; while (i < KEYS.length - 2 && p > KEYS[i + 1].p) i++;
    var a = KEYS[i], b = KEYS[i + 1], t = ease(clamp((p - a.p) / (b.p - a.p), 0, 1));
    var o = a.v.map(function (x, j) { return x + (b.v[j] - x) * t; });
    // the focus marker belongs to whichever part the camera is on, and only once it has settled there
    var ring = a.ring && a.ring === b.ring ? a.ring : (t > .85 ? b.ring : t < .15 ? a.ring : 0);
    return { fx: o[0], fy: o[1], s: o[2], tx: o[3], ty: o[4], ry: o[5], rx: o[6], dof: o[7], lamp: o[8], la: o[9], ring: ring };
  }

  var FADE = .02;
  function vis(p, a, b) { return Math.min(clamp((p - a) / FADE + 1, 0, 1), clamp((b - p) / FADE + 1, 0, 1)); }

  var target = 0, prog = 0, last = -1, fitOn = false, counted = false, lastT = performance.now();
  function readScroll() {
    var top = tour.getBoundingClientRect().top + scrollY, max = tour.offsetHeight - innerHeight;
    target = clamp((scrollY - top) / max, 0, 1);
    var r = tour.getBoundingClientRect();
    if (nav) nav.classList.toggle("is-on-dark", r.top < 90 && r.bottom > 90);
    document.body.classList.toggle("is-touring", r.top <= 1 && r.bottom >= innerHeight - 1);
  }

  function render(p, time) {
    var k = sample(p);
    var px = k.fx * BW, py = k.fy * BH;
    var dx = k.tx * SW - ((SW - BW) / 2 + px), dy = k.ty * SH - ((SH - BH) / 2 + py);
    cam.style.transformOrigin = px + "px " + py + "px";
    var breathe = reduced ? 0 : Math.sin(time / 2400) * .6; // a slow handheld sway, so a held shot never looks frozen
    cam.style.transform = "translate3d(" + dx.toFixed(1) + "px," + dy.toFixed(1) + "px,0) rotateX(" + (k.rx + breathe * .4).toFixed(2) + "deg) rotateY(" + (k.ry + breathe).toFixed(2) + "deg) scale(" + k.s.toFixed(4) + ")";
    var part = PART[k.ring] || [k.fx, k.fy];
    cam.style.opacity = phone.matches ? (1 - clamp((p - .86) / .035, 0, 1)).toFixed(3) : 1;
    bike.style.setProperty("--lamp", k.lamp.toFixed(3));
    bike.style.setProperty("--la", (k.la + k.ry * 2).toFixed(1) + "deg");
    bike.style.setProperty("--fx", (part[0] * 100) + "%"); bike.style.setProperty("--fy", (part[1] * 100) + "%");
    bike.style.setProperty("--inv", (1 / k.s).toFixed(4));
    focus.style.opacity = k.ring ? Math.min(1, k.dof) : 0;
    if (k.ring) focusNo.textContent = k.ring;
    spot.style.setProperty("--spx", (k.tx * 100).toFixed(1) + "%");

    beats.forEach(function (b) {
      var v = vis(p, b.a, b.b);
      if (Math.abs(v - b.v) < .001) return;
      b.v = v; b.el.style.opacity = v; b.el.style.visibility = v < .01 ? "hidden" : "visible";
      var lift = ((1 - v) * 18).toFixed(1) + "px";
      b.el.style.translate = "0 " + lift;
    });
    steps.forEach(function (li, i) { var c = cards[i]; li.style.setProperty("--f", clamp((p - c.a + .03) / (c.b - c.a), 0, 1).toFixed(3)); });
    steps[0].parentNode.style.opacity = p > .1 && p < .88 ? 1 : 0;

    var fit = fitCard && vis(p, .635, .725) > .5;
    if (fit !== fitOn && window.dcbFit) { fitOn = fit; window.dcbFit(fit); }
    if (!counted && p > .9) { counted = true; countUp(); }
  }

  function countUp() {
    tour.querySelectorAll("[data-tour-count]").forEach(function (el) {
      var to = +el.dataset.tourCount;
      if (!window.gsap || reduced) return;
      var o = { v: 0 }; gsap.to(o, { v: to, duration: 1.2, ease: "power3.out", onUpdate: function () { el.textContent = Math.round(o.v); } });
    });
  }

  function frame(now) {
    var dt = Math.min((now - lastT) / 1000, .05); lastT = now;
    prog += (target - prog) * (reduced ? 1 : 1 - Math.pow(.002, dt)); // damped follow: scroll feels weighted without a smooth-scroll library
    var r = tour.getBoundingClientRect();
    if (r.bottom > -50 && r.top < innerHeight + 50 && (Math.abs(prog - last) > .00005 || !reduced)) { render(prog, now); last = prog; }
    requestAnimationFrame(frame);
  }

  addEventListener("resize", function () { layout(); readScroll(); render(prog, performance.now()); });
  addEventListener("scroll", readScroll, { passive: true });
  layout(); readScroll();
  var q = location.search.match(/[?&]tour=([\d.]+)/); // ?tour=0.4 jumps to a point in the tour (for review links and screenshots)
  if (q) addEventListener("load", function () {
    var top = tour.getBoundingClientRect().top + scrollY;
    scrollTo(0, top + parseFloat(q[1]) * (tour.offsetHeight - innerHeight) + 1);
    readScroll(); prog = target;
  });
  prog = target;
  requestAnimationFrame(frame);
})();

// Chapter rail: dots down the right edge for each section of the home page; the current one is gold with its name.
(function () {
  var rail = document.querySelector("[data-rail]");
  if (!rail) return;
  var links = [].slice.call(rail.querySelectorAll("[data-rail-link]")).map(function (a) { return { a: a, el: document.querySelector(a.getAttribute("href")) }; })
    .filter(function (l) { return l.el; });
  var hero = document.querySelector(".hero_component"), quiet;
  function upd() {
    rail.classList.toggle("is-on", scrollY > (hero ? hero.offsetHeight * .6 : 200));
    var cur = links[0];
    links.forEach(function (l) { if (l.el.getBoundingClientRect().top < innerHeight * .45) cur = l; });
    links.forEach(function (l) { l.a.classList.toggle("is-current", l === cur); });
    // the label shows while you're moving, then tucks away
    rail.classList.remove("is-quiet"); clearTimeout(quiet); quiet = setTimeout(function () { rail.classList.add("is-quiet"); }, 1400);
  }
  addEventListener("scroll", upd, { passive: true }); upd();
})();

