/* ---- appsim.js ---- */
// "Ian's media" variant only. App sim on our station map: plays a ride on its own (find a station, scan, ride over the
// bridge, dock) and lets you take over: tap a pin for its sheet, Nearby picks the closest station, Scan or "Scan to unlock"
// starts a ride. Leave it alone for a few seconds and it picks the loop back up. Station pins: same % positions as the
// stations section (data-x / data-y on .board_row); bike and dock counts are illustrative.
(function () {
  var STATIONS = [
    ["Downtown Marina", 41.2, 39.4], ["Lightner Museum", 37.6, 37.0], ["Flagler College", 33.6, 25.9], ["Visitors Information Center", 30.6, 25.9],
    ["City Plaza", 35.1, 43.5], ["The Amp", 74.7, 58.6], ["Osprey Tacos", 96.3, 94.0], ["Lighthouse Park", 66.9, 44.4], ["DOS", 53.5, 34.3],
    ["Hypolita & Cordova", 35.6, 32.4], ["Lincolnville Museum", 35.5, 50.7], ["BOG", 16.9, 36.1], ["Malaga & Valencia", 27.0, 33.8],
    ["San Marco & Cincinnati", 28.0, 15.3]];
  var ME = [36.8, 46.5], DEMO_A = 4; // you, near the Plaza; the demo rides City Plaza -> Lighthouse Park (real route)
  var ICON = {
    pin: '<svg viewBox="0 0 24 24"><path d="M12 21s-6.5-6.1-6.5-11a6.5 6.5 0 0 1 13 0c0 4.9-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.3"/></svg>',
    scan: '<svg viewBox="0 0 24 24"><path d="M4 8V5a1 1 0 0 1 1-1h3M16 4h3a1 1 0 0 1 1 1v3M20 16v3a1 1 0 0 1-1 1h-3M8 20H5a1 1 0 0 1-1-1v-3"/><path d="M9 9h2v2H9zM13 13h2v2h-2zM13 9h2v2h-2zM9 13h2v2H9z"/></svg>',
    ok: '<svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>'};

  function build(root, img) {
    var hits = STATIONS.map(function (s, i) { return '<span class="appsim_hit" data-i="' + i + '" style="left:' + s[1] + '%;top:' + s[2] + '%"></span>'; }).join("");
    root.innerHTML =
      '<div class="appsim_map"><div class="appsim_cam"><img src="' + img + '" alt="">' +
        '<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path class="appsim_route" pathLength="1" d=""/></svg>' + hits +
        '<span class="appsim_me" style="left:' + ME[0] + '%;top:' + ME[1] + '%"></span><span class="appsim_sel"></span><span class="appsim_bike"></span></div></div>' +
      '<div class="appsim_top"><span class="appsim_menu"><i></i></span><span class="appsim_search">Find a station</span></div>' +
      '<div class="appsim_hint">Tap a station</div>' +
      '<div class="appsim_fabs"><button class="appsim_fab" data-nearby>' + ICON.pin + 'Nearby</button><button class="appsim_fab" data-scan>' + ICON.scan + 'Scan</button></div>' +
      '<div class="appsim_sheet"><div class="appsim_grab"></div><div class="appsim_head"><span class="appsim_logo">D</span><span><b class="appsim_name"></b>' +
        '<span class="appsim_sub">DRIFTERS City Bike Share</span><span class="appsim_avail"></span></span></div>' +
        '<div class="appsim_fare"><b>$5.50 + $4.50 / 1 hour</b><span>Rent up to 4 at a time</span></div>' +
        '<button class="appsim_cta" data-unlock>' + ICON.scan + 'Scan to unlock</button></div>' +
      '<div class="appsim_scan"><div class="appsim_qr"><i></i><i></i><i></i><i></i><span class="appsim_laser"></span></div>' +
        '<span class="appsim_ok">' + ICON.ok + '</span><b class="appsim_scan-t">Scan the code on the bike</b><p class="appsim_scan-p">It\'s on the basket panel.</p></div>' +
      '<div class="appsim_pill"><i></i><b>00:00</b></div>' +
      '<div class="appsim_card"><b class="appsim_card-t"></b><span class="appsim_card-s"></span><button class="appsim_cta appsim_card-b" data-end>End ride</button></div>';
  }

  document.querySelectorAll("[data-appsim]").forEach(function (root) {
    build(root, root.dataset.appsim);
    var $ = function (s) { return root.querySelector(s); };
    var cam = $(".appsim_cam"), sel = $(".appsim_sel"), bike = $(".appsim_bike"), route = $(".appsim_route"), pill = $(".appsim_pill b");
    var state = "map", cur = null, timers = [], raf = 0, auto = true, idle = 0, visible = false;

    function size() { var h = root.clientHeight; cam.style.width = cam.style.height = h + "px"; return h; }
    function view(x, y, k, cy) {
      var w = root.clientWidth, h = root.clientHeight, S = size();
      var tx = Math.min(0, Math.max(w - S * k, w / 2 - x / 100 * S * k)), ty = Math.min(0, Math.max(h - S * k, h * (cy || .5) - y / 100 * S * k));
      cam.style.transform = "translate(" + tx + "px," + ty + "px) scale(" + k + ")";
      cam.style.setProperty("--inv", 1 / k);
      route.style.strokeWidth = (3.5 * 100 / (S * k)).toFixed(3); // 3.5px on screen at any zoom
    }
    function set(s) {
      state = s;
      ["map", "sheet", "scan", "unlocked", "ride", "done"].forEach(function (n) { root.classList.toggle("is-" + n, n === s || (s === "unlocked" && n === "scan")); });
    }
    function later(fn, ms) { timers.push(setTimeout(fn, ms)); }
    function clear() { timers.forEach(clearTimeout); timers = []; cancelAnimationFrame(raf); }
    function counts(i) { var b = 3 + (i * 5) % 7; return "<b>" + b + "</b> bikes · " + (14 - b) + " open docks"; }
    function mark(i) { var s = STATIONS[i]; sel.style.left = s[1] + "%"; sel.style.top = s[2] + "%"; sel.classList.add("is-on"); }

    function home() { clear(); cur = null; sel.classList.remove("is-on"); route.setAttribute("d", ""); set("map"); view(ME[0], ME[1] - 4, 1.7); }
    function open(i, keep) {
      if (!keep) clear(); cur = i; var s = STATIONS[i];
      $(".appsim_name").textContent = s[0]; $(".appsim_avail").innerHTML = counts(i);
      mark(i); route.setAttribute("d", ""); set("sheet"); view(s[1], s[2], 2.2, .34);
    }
    function nearest() {
      var best = 0, d = 1e9;
      STATIONS.forEach(function (s, i) { var dd = Math.pow(s[1] - ME[0], 2) + Math.pow(s[2] - ME[1], 2); if (dd < d) { d = dd; best = i; } });
      return best;
    }
    function scan() {
      clear(); if (cur === null) open(nearest());
      var from = cur;
      $(".appsim_scan-t").textContent = "Scan the code on the bike"; $(".appsim_scan-p").textContent = "It's on the basket panel.";
      set("scan");
      later(function () { set("unlocked"); $(".appsim_scan-t").textContent = "Bike 027 unlocked"; $(".appsim_scan-p").textContent = "Pull it from the dock and ride."; }, 1700);
      later(function () { ride(from); }, 2900);
    }
    // the ride follows a real street route (routes.py -> appsim-routes.js): every station rides to Lighthouse Park, which rides to the Marina
    function ride(a) {
      var R = window.APPSIM_ROUTES[a], b = R.to, B = STATIONS[b], pts = R.pts;
      var xs = pts.map(function (p) { return p[0]; }), ys = pts.map(function (p) { return p[1]; });
      var x0 = Math.min.apply(0, xs), x1 = Math.max.apply(0, xs), y0 = Math.min.apply(0, ys), y1 = Math.max.apply(0, ys);
      var w = root.clientWidth, h = root.clientHeight, S = size();
      var k = Math.max(1, Math.min(2.4, (w / S) * 100 / (x1 - x0 + 12), (h / S) * 100 * .55 / (y1 - y0 + 12)));
      route.setAttribute("d", "M" + pts.map(function (p) { return p[0] + " " + p[1]; }).join(" L"));
      $(".appsim_card-t").textContent = "Riding to " + B[0]; $(".appsim_card-s").textContent = R.km + " km" + (x0 < 42 && x1 > 47 ? " · over the Bridge of Lions" : ""); // the river runs x 42-47%
      $(".appsim_card-b").textContent = "End ride"; sel.classList.remove("is-on");
      view((x0 + x1) / 2, (y0 + y1) / 2, k, .4);
      requestAnimationFrame(function () { set("ride"); });
      // cumulative length so the bike moves at an even pace along the route
      var len = [0];
      for (var i = 1; i < pts.length; i++) len.push(len[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
      var total = len[len.length - 1], mins = R.min, t0 = performance.now(), dur = 3200;
      (function step(now) {
        var p = Math.min(1, (now - t0) / dur), e = p < .5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2, at = e * total, n = 1;
        while (n < len.length - 1 && len[n] < at) n++;
        var f = (at - len[n - 1]) / ((len[n] - len[n - 1]) || 1), secs = Math.round(e * mins * 60);
        bike.style.left = pts[n - 1][0] + (pts[n][0] - pts[n - 1][0]) * f + "%"; bike.style.top = pts[n - 1][1] + (pts[n][1] - pts[n - 1][1]) * f + "%";
        pill.textContent = ("0" + Math.floor(secs / 60)).slice(-2) + ":" + ("0" + secs % 60).slice(-2);
        if (p < 1) raf = requestAnimationFrame(step); else done(b, mins);
      })(t0);
    }
    function done(b, mins) {
      later(function () {
        mark(b); set("done");
        $(".appsim_card-t").textContent = "Ride ended"; $(".appsim_card-s").textContent = "Docked at " + STATIONS[b][0] + " · " + mins + " min";
        $(".appsim_card-b").textContent = "Locked and docked";
        if (auto) later(loop, 2600);
      }, 500);
    }
    function loop() {
      home();
      later(function () { open(DEMO_A, true); }, 2200);
      later(function () { $(".appsim_cta").classList.add("is-tap"); }, 4800);
      later(function () { $(".appsim_cta").classList.remove("is-tap"); scan(); }, 5300);
    }
    function touch() { auto = false; clearTimeout(idle); idle = setTimeout(function () { auto = true; if (visible) loop(); }, 9000); }

    root.addEventListener("click", function (e) {
      var t = e.target.closest("[data-i],[data-nearby],[data-scan],[data-unlock],[data-end]");
      touch();
      if (!t) { if (state === "sheet" || state === "done") home(); return; }
      if (t.dataset.i != null) open(+t.dataset.i);
      else if ("nearby" in t.dataset) open(nearest());
      else if ("scan" in t.dataset || "unlock" in t.dataset) scan();
      else if ("end" in t.dataset && state === "done") home();
    });
    new IntersectionObserver(function (en) {
      visible = en[0].isIntersecting;
      if (visible && auto) loop(); else if (!visible) clear();
    }).observe(root);
    window.addEventListener("resize", function () { if (state === "map") view(ME[0], ME[1] - 4, 1.7); });
    home();
  });
})();

/* ---- app-link.js ---- */
// Island: data-dcb-app-link. iPhone -> App Store, Android -> Google Play, everything else keeps its href (/download).
(function () {
  var APP_STORE = "https://apps.apple.com/us/app/drifters-city-bike/id6755121198", GOOGLE_PLAY = "#google-play-url-pending"; // App Store confirmed 2026-10-29; Google Play pending from Ian
  var ua = navigator.userAgent || "";
  var t = /iPhone|iPad|iPod/i.test(ua) ? APP_STORE : /Android/i.test(ua) ? GOOGLE_PLAY : null;
  if (t) document.querySelectorAll("[data-dcb-app-link]").forEach(function (a) { a.href = t; });
})();

/* ---- mux-video.js ---- */
// Island: data-dcb-mux="<playback id>" on a muted <video> (Webflow custom element). Safari plays Mux HLS natively;
// other browsers get a static MP4: 480p on phones, tablets and Save-Data, 720p on large screens. No hls.js.
// Reduced motion: no autoplay, the poster stays. JS off: no src, the poster stays. Playback ids: webflow/mux.json.
(function () {
  var vids = document.querySelectorAll("video[data-dcb-mux]");
  if (!vids.length) return;
  var still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var conn = navigator.connection || {};
  var small = window.innerWidth < 992 || conn.saveData;
  vids.forEach(function (v) {
    var id = v.getAttribute("data-dcb-mux");
    if (!id) return;
    if (!v.getAttribute("poster")) v.poster = "https://image.mux.com/" + id + "/thumbnail.webp?time=0&width=720";
    if (still) return;
    v.muted = true; // Webflow reserves autoplay/muted/loop/playsinline as attributes, so the island sets them
    v.loop = true;
    v.autoplay = true;
    v.playsInline = true;
    v.setAttribute("playsinline", "");
    v.src = v.canPlayType("application/vnd.apple.mpegurl")
      ? "https://stream.mux.com/" + id + ".m3u8"
      : "https://stream.mux.com/" + id + "/" + (small ? "480p" : "720p") + ".mp4";
    var p = v.play();
    if (p && p.catch) p.catch(function () {});
  });
})();
